{
  "steps": [
    {
      "title": "დაკეტე წყალი",
      "text": "მოატრიალე ონკანი საათის ისრის მიმართულებით ბოლომდე. შემდეგ მეორეც დაკეტე.",
      "focus": ["p1", "p2"],
      "avoid": [],
      "markers": [],
      "arrows": [
        {"part": "p1", "type": "rotate", "dir": "cw"},
        {"part": "p2", "type": "rotate", "dir": "cw"}
      ],
      "tools": [],
      "warn": "ვენტილები ძალით არ გადაატრიალო."
    },
    {
      "title": "ჩადგი ვედრო სიფონის ქვეშ",
      "text": "სიფონში წყალი დგას. გახსნისას ჩამოიღვრება, ამიტომ ვედრო ან ღრმა თასი პირდაპირ მის ქვეშ დადგი.",
      "focus": [],
      "avoid": [],
      "markers": [],
      "arrows": [],
      "tools": ["ვედრო ან ღრმა თასი"],
      "warn": "დასადგმელი ვედრო ან თასი ფოტოზე არ ჩანს და მინიჭებული ID არ აქვს."
    },
    {
      "title": "მოუშვი ქანჩი",
      "text": "ეს ქანჩი ჟონავს. ხელით მოუშვი საათის ისრის საწინააღმდეგოდ. პლასტმასისაა, გასაღები არ დაგჭირდება.",
      "focus": ["p4"],
      "avoid": [],
      "markers": [
        {"part": "p4", "label": "შეერთება ხილული წვეთით", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p4", "type": "rotate", "dir": "ccw"}
      ],
      "tools": [],
      "warn": "არჩეულია მარჯვენა ქანჩი p4: მის ქვედა კიდეზე ჩანს წვეთი და ზედაპირზე სველი კვალი. ეს ყველაზე სავარაუდო სამიზნეა, თუმცა ფოტოთი გაჟონვის ზუსტი წყარო ვერ დასტურდება. სიფონი ხელით დაიჭირე."
    },
    {
      "title": "შეამოწმე შუასადები",
      "text": "მოხსენი სიფონი და ნახე ქანჩის შიგნით რეზინის რგოლი. თუ დაბზარულია ან გვერდზეა გადაწეული, შეცვალე. ზომა: 40 მმ.",
      "focus": ["p3", "p4"],
      "avoid": [],
      "markers": [],
      "arrows": [],
      "tools": [],
      "warn": "p3 არის მოსახსნელი სიფონი, p4 — შესამოწმებელი შეერთება. შიდა რეზინის რგოლი ფოტოზე არ ჩანს და ID არ აქვს. 40 მმ მოცემულია ინსტრუქციაში და ფოტოთი არ დასტურდება — ჩანაცვლებამდე გადაამოწმე ზომა. მხოლოდ გადაწეული, დაუზიანებელი შუასადები შესაძლოა სწორად ჩასმას საჭიროებდეს."
    },
    {
      "title": "მოუჭირე და შეამოწმე",
      "text": "ხელით მოუჭირე ბოლომდე, შემდეგ კიდევ მეოთხედი ბრუნი. გახსენი წყალი და ერთი წუთი დააკვირდი.",
      "focus": ["p4", "p1", "p2"],
      "avoid": [],
      "markers": [
        {"part": "p4", "label": "შეამოწმე გაჟონვა", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p4", "type": "rotate", "dir": "cw"},
        {"part": "p1", "type": "rotate", "dir": "ccw"},
        {"part": "p2", "type": "rotate", "dir": "ccw"}
      ],
      "tools": [],
      "warn": "დამატებითი მეოთხედი ბრუნი უნივერსალური მოთხოვნა არ არის: დაიცავი მწარმოებლის მითითება და პლასტმასის ქანჩი ძალით არ გადაჭიმო. ვენტილების გახსნის შემდეგ ნიჟარის ონკანიც გაუშვი, რათა სიფონში წყალი გაიაროს; ეს ონკანი ფოტოზე არ ჩანს."
    }
  ],
  "unknown_parts": [
    "დასადგმელი ვედრო ან ღრმა თასი",
    "ქანჩის შიგნით არსებული რეზინის შუასადები",
    "ნიჟარის ონკანი, რომლითაც შემოწმებისას წყალი უნდა გაუშვა"
  ]
}
